questionvariables.text:
/* Randomized midline temperature */
D: 16+rand(7);

/* Randomized amplitude */
A: 3+rand(5);

/* Period of the daily cycle */
P: 24;

/* Time of maximum temperature */
C: 12+rand(5);

/* Temperature model */
T: D+A*cos((2*%pi/P)*(t-C));

/* JSXGraph expression */
fx: D+A*cos((2*%pi/P)*(x-C));

/* Model answers */
ta1: A;
ta2: D;
ta3: P;
ta4: C;
